#include "unity.h"
#include "buffer.h"
#include "helpers.h"

// Forward declaration for stdout_capture_t and capture functions
// (Normally would be in a header, but added here for minimal fix)
typedef struct stdout_capture_t stdout_capture_t;
stdout_capture_t *capture_stdout_start(void);
char *capture_stdout_stop(stdout_capture_t *cap);

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_print_prints_hex_for_nonempty_buffer(void) {
    // Setup: create a buffer with known data
    // We'll use 10 bytes: {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20}
    size_t buf_len = 10;
    buffer_t *buf = buffer_new_with_size(buf_len);
    TEST_ASSERT_NOT_NULL(buf);
    // Fill buffer->alloc with test data
    unsigned char test_data[10] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20};
    for (size_t i = 0; i < buf_len; ++i) {
        buf->alloc[i] = test_data[i];
    }
    buf->len = buf_len;

    // Capture stdout
    stdout_capture_t *cap = capture_stdout_start();

    // Test: call buffer_print
    buffer_print(buf);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Expected output:
    // "
  01 23 45 67 89 ab cd ef
  10 20
"
    // (8 bytes per line, then 2 bytes on the next line, each line starts with a space)
    const char *expected =
        "
"
        "  01 23 45 67 89 ab cd ef
"
        "  10 20
";

    TEST_ASSERT_EQUAL_STRING(expected, output);

    // Cleanup
    free(output);
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_print_prints_hex_for_nonempty_buffer);
    return UNITY_END();
}


