// Function: capture_stdout_start (from helper pool)
/* Created by capture_stdout_start(), freed by capture_stdout_stop(). */
typedef struct {
    int saved_stdout_fd;    /* Original stdout file descriptor */
    int pipe_read_fd;       /* Read end of pipe */
    int pipe_write_fd;      /* Write end of pipe */
    char *buffer;           /* Captured output buffer */
    size_t buffer_size;     /* Size of allocated buffer */
} stdout_capture_t;

// Minimal implementation for POSIX systems
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = (stdout_capture_t *)malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->saved_stdout_fd = dup(fileno(stdout));
    fflush(stdout);
    dup2(pipefd[1], fileno(stdout));
    close(pipefd[1]);
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = -1; // closed
    cap->buffer = NULL;
    cap->buffer_size = 0;
    return cap;
}

char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    fflush(stdout);
    dup2(cap->saved_stdout_fd, fileno(stdout));
    close(cap->saved_stdout_fd);
    // Read from pipe
    size_t bufsize = 4096;
    char *buf = (char *)malloc(bufsize);
    if (!buf) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    size_t total = 0;
    ssize_t n;
    while ((n = read(cap->pipe_read_fd, buf + total, bufsize - total - 1)) > 0) {
        total += n;
        if (total > bufsize - 2) {
            bufsize *= 2;
            char *tmp = realloc(buf, bufsize);
            if (!tmp) break;
            buf = tmp;
        }
    }
    buf[total] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buf;
}

